#!/nix/store/gxzhl7aaiid7zp3y47jqqiq7zg5mqpwp-python3-3.14.6/bin/python
"""Small durable HTTP record service for the builder deployment slot."""

import hashlib
import os
import tempfile
import threading
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from urllib.parse import unquote, urlsplit

HOST = "0.0.0.0"
PORT = 8080
DATA_DIR = "/var/lib/builder-app/records"

os.makedirs(DATA_DIR, mode=0o755, exist_ok=True)
_store_lock = threading.RLock()


def record_path(record_id: str) -> str:
    # A digest keeps URL-derived names out of the filesystem and prevents
    # traversal while still allowing any non-slash URL id.
    key = hashlib.sha256(record_id.encode("utf-8")).hexdigest()
    return os.path.join(DATA_DIR, key)


def save_record(record_id: str, body: bytes) -> None:
    destination = record_path(record_id)
    fd, temporary = tempfile.mkstemp(prefix=".record-", dir=DATA_DIR)
    try:
        with os.fdopen(fd, "wb") as output:
            output.write(body)
            output.flush()
            os.fsync(output.fileno())
        os.replace(temporary, destination)
        # Ensure the rename itself is durable across a host power loss/reboot.
        directory_fd = os.open(DATA_DIR, os.O_RDONLY | getattr(os, "O_DIRECTORY", 0))
        try:
            os.fsync(directory_fd)
        finally:
            os.close(directory_fd)
    except BaseException:
        try:
            os.unlink(temporary)
        except FileNotFoundError:
            pass
        raise


def load_record(record_id: str) -> bytes | None:
    try:
        with open(record_path(record_id), "rb") as stored:
            return stored.read()
    except FileNotFoundError:
        return None


def requested_id(path: str) -> str | None:
    parsed = urlsplit(path)
    if parsed.query or parsed.fragment:
        return None
    prefix = "/records/"
    if not parsed.path.startswith(prefix):
        return None
    encoded_id = parsed.path[len(prefix):]
    if not encoded_id or "/" in encoded_id:
        return None
    try:
        record_id = unquote(encoded_id, errors="strict")
    except UnicodeDecodeError:
        return None
    if not record_id or "/" in record_id or "\\" in record_id or "\x00" in record_id:
        return None
    return record_id


class Handler(BaseHTTPRequestHandler):
    protocol_version = "HTTP/1.1"

    def log_message(self, format: str, *args: object) -> None:
        # Keep system journal useful without writing access logs to stdout.
        super().log_message(format, *args)

    def do_GET(self) -> None:
        if urlsplit(self.path).path == "/health" and not urlsplit(self.path).query:
            self._send(200, b"ready")
            return
        record_id = requested_id(self.path)
        if record_id is None:
            self._send(404, b"")
            return
        with _store_lock:
            body = load_record(record_id)
        if body is None:
            self._send(404, b"")
        else:
            self._send(200, body)

    def do_PUT(self) -> None:
        record_id = requested_id(self.path)
        if record_id is None:
            self._send(404, b"")
            return
        header = self.headers.get("Content-Length")
        if header is None:
            self._send(411, b"")
            return
        try:
            length = int(header)
        except ValueError:
            self._send(400, b"")
            return
        if length < 0:
            self._send(400, b"")
            return
        body = self.rfile.read(length)
        if len(body) != length:
            self._send(400, b"")
            return
        with _store_lock:
            save_record(record_id, body)
        self._send(204, b"")

    def _send(self, status: int, body: bytes) -> None:
        self.send_response(status)
        self.send_header("Content-Length", str(len(body)))
        self.send_header("Connection", "close")
        self.end_headers()
        if body:
            self.wfile.write(body)


class Server(ThreadingHTTPServer):
    allow_reuse_address = True
    daemon_threads = True


if __name__ == "__main__":
    server = Server((HOST, PORT), Handler)
    try:
        server.serve_forever()
    finally:
        server.server_close()
